code.source:
#include <iostream>
using namespace std;

class Animal {
public:
    virtual ~Animal() { cout << "Animal gone" << endl; }
};

class Dog : public Animal {
public:
    ~Dog() override { cout << "Dog gone" << endl; }
};

int main() {
    Animal* a = new Dog;
    delete a;
    return 0;
}

#include <iostream>
#include <memory>
using namespace std;

class Animal {
public:
    virtual ~Animal() { cout << "Animal gone" << endl; }
};

class Dog : public Animal {
public:
    ~Dog() override { cout << "Dog gone" << endl; }
};

int main() {
    unique_ptr<Animal> a = make_unique<Dog>();
    cout << "working" << endl;
    return 0;
}

